import path from "node:path";

/**
 * The bundled public runtime adapter reads the taxonomy at MODULE LOAD: its import graph reaches
 * `@role-model-router/core`, whose taxonomy module resolves its data root from
 * `ROLE_MODEL_TAXONOMY_DATA_ROOT`, a path beside the SEA executable, `--repo-root`/`ROLE_MODEL_REPO_ROOT`,
 * or the process cwd.
 *
 * A private script or test that imports the adapter runs with the cwd inside the PRIVATE checkout, so
 * none of those fallbacks can see the PUBLIC worktree's data, and the import dies with
 * `Unable to read taxonomy data file manifest.json`. Every such consumer already knows the public
 * worktree, so this points the adapter at it before the import.
 *
 * Returns the root it resolved, or `undefined` when neither an explicit root nor a public worktree is known.
 */
export function ensureTaxonomyDataRoot(publicWorktree = process.env.ROLE_MODEL_PUBLIC_WORKTREE) {
  const existing = process.env.ROLE_MODEL_TAXONOMY_DATA_ROOT;
  if (existing) return existing;
  if (!publicWorktree) return undefined;
  const root = path.join(
    publicWorktree,
    "role-model-router",
    "packages",
    "core",
    "data",
    "taxonomy",
  );
  process.env.ROLE_MODEL_TAXONOMY_DATA_ROOT = root;
  return root;
}
